import type { Handler } from '../../types/Handler'
import { tryCatch, tryCatchAsync } from '../../utils/TryCatch'
import { BaseEvent } from '../../types/BaseEvent'
import { DependencyContainer } from 'tsyringe-neo'

export type EventCallback = (event: BaseEvent) => void | Promise<void>
export type Unsubscribe = () => void

/**
 * Resolve every event name a Handler subscribes to. EventHandlers (SPEC-12)
 * expose `events: readonly string[]` for both single-event and multi-event
 * forms; non-event Handlers fall back to `handler.name`.
 */
export function handlerEventNames(handler: Handler): readonly string[] {
	const events = (handler as Handler & { events?: readonly string[] }).events
	if (Array.isArray(events) && events.length > 0) {
		return events
	}
	return [handler.name]
}

export abstract class Mediator {
	abstract register(handler: Handler): void
	abstract execute<T extends Handler>(handler: T['name'], input: T['input']): Promise<T['output']>
	abstract publish(event: BaseEvent): Promise<void>
	abstract dispatch(event: BaseEvent): Promise<void>
	abstract removeAllListeners(): void
	abstract registerCallback(callback: EventCallback, eventName?: string): Unsubscribe

	// Lifecycle hooks — default no-op. Concrete mediators with networked transports
	// (Redis, Kafka, ...) override to open/close connections.
	async start(): Promise<void> {}
	async stop(): Promise<void> {}

	static async register(
		container: DependencyContainer,
		mediator: Mediator,
		handlers: Record<string, new (...args: any[]) => Handler>,
	): Promise<number> {
		const handlerInstances: Handler[] = []
		let successCount = 0

		for (const [handlerName, HandlerClass] of Object.entries(handlers)) {
			if (typeof HandlerClass === 'function' && handlerName !== 'default') {
				const result = tryCatch(() => {
					const handlerInstance = container.resolve(HandlerClass).bindContainer(container)
					handlerInstances.push(handlerInstance)
					successCount++
				})
				if (!result.success) {
					console.warn(`Failed to resolve Handler ${handlerName}:`, result.error)
				}
			}
		}

		for (const handler of handlerInstances) {
			const result = await tryCatchAsync(async () => {
				await mediator.register(handler)
			})
			if (!result.success) {
				console.warn(`Failed to register Handler:`, result.error)
				successCount--
			}
		}

		console.log(`✅ Registered ${successCount} Handlers`)
		return successCount
	}
}

export abstract class InternalMediator extends Mediator {}

export abstract class ExternalMediator extends Mediator {}

import { Id } from '../objects/Id'
import { ValueObject } from '../objects/ValueObject'
import { BaseError } from '../types/BaseError'
import type { BaseDomainEvent, DomainEventSchemaConstraint } from '../types/BaseDomainEvent'
import type { z, ZodObject, ZodRawShape, ZodType } from 'zod'
import type { BaseDomainErrors } from '../errors'

/** Widest accepted domain event shape — any subclass schema matching the constraint. */
type AnyDomainEvent = BaseDomainEvent<DomainEventSchemaConstraint>

export interface BaseEntityProps {
	id?: Id | string
	createdAt?: Date
	updatedAt?: Date
	version?: number
}

export abstract class BaseEntity<T extends ZodObject = ZodObject<ZodRawShape>> extends ValueObject {
	static schema?: ZodType
	private domainEvents: AnyDomainEvent[] = []

	id: Id = new Id()
	createdAt: Date = new Date()
	updatedAt: Date = new Date()
	version = 1

	constructor(props?: z.input<T> & BaseEntityProps) {
		super()
		if (!props) return

		const schema = (this.constructor as typeof BaseEntity).schema
		const result = schema?.safeParse(props)

		if (result && !result.success) {
			throw new BaseError<BaseDomainErrors>('INVALID_ENTITY', result.error.issues[0]?.message)
		}

		// Assign transformed domain props (schema applies .transform())
		Object.assign(this, result?.data ?? props)

		// Handle base entity props explicitly (id accepts string or Id)
		if (props.id != null) this.id = props.id instanceof Id ? props.id : new Id(props.id as string)
		if (props.createdAt != null) this.createdAt = props.createdAt
		if (props.updatedAt != null) this.updatedAt = props.updatedAt
		if (props.version != null) this.version = props.version
	}

	protected validate(): void {
		const schema = (this.constructor as typeof BaseEntity).schema
		if (!schema) return
		const result = schema.safeParse(this)
		if (!result.success) throw new BaseError(result.error.issues[0]!.message)
		Object.assign(this, result.data)
	}

	incrementVersion(): void {
		this.version++
		this.updatedAt = new Date()
	}

	/**
	 * Raise a domain event. Called from inside behavior methods when an
	 * aggregate transitions to a new state. Events accumulate until
	 * `pullDomainEvents()` is called (typically by a use case or handler
	 * that then persists them via `domainEventRepository.save`).
	 */
	protected addDomainEvent(event: AnyDomainEvent): void {
		this.domainEvents.push(event)
	}

	/**
	 * Drain and return all pending domain events. Clears the internal buffer.
	 * Callers iterate the returned array and persist each event via
	 * `domainEventRepository.save(event, tx)` inside the same transaction as
	 * the entity write.
	 */
	pullDomainEvents(): AnyDomainEvent[] {
		const events = this.domainEvents
		this.domainEvents = []
		return events
	}

	static transformed() {
		// biome-ignore lint/complexity/noThisInStatic: polymorphic this pattern — subclasses call BaseEntity.transformed() and `this` must resolve to the subclass constructor at runtime
		const Cls = this as unknown as { schema: ZodType; new (props: unknown): BaseEntity }
		return Cls.schema.input().transform((v: unknown) => new Cls(v))
	}
}

export type Transaction = unknown

export abstract class UnitOfWorkFactory {
	abstract create(): UnitOfWork
}

export abstract class UnitOfWork<T = Transaction> {
	abstract transaction<Return>(fn: (tx: T) => Promise<Return>): Promise<Return>
}

import { BaseEntity } from './BaseEntity'
import type { ZodObject, ZodRawShape } from 'zod'

export class AggregateRoot<T extends ZodObject = ZodObject<ZodRawShape>> extends BaseEntity<T> {}

import type { ZodType } from 'zod'
import type { DependencyContainer } from 'tsyringe-neo'
import { container as rootContainer } from 'tsyringe-neo'
import { Router } from './Router'
import type { Controller } from './Controller'
import type { Middleware, MiddlewareClass } from './Middleware'
import { InternalMediator, ExternalMediator, Mediator } from '../services/Mediator'
import { CommandQueue } from '../services/CommandQueue'
import { autoTrace } from '../utils/Tracing'
import { registerAll, type InstanceRegistry } from './Registry'
import type { Handler } from './Handler'
import type { Projector } from './Projector'
import { tryCatch } from '../utils/TryCatch'

type Constructor<T = object> = new (...args: any[]) => T
type MiddlewareInput = Record<string, Constructor<Middleware>> | MiddlewareClass[] | []
type HandlerRecord = Record<string, new (...args: any[]) => Handler>

export interface JobDefinition {
	handler: new (...args: any[]) => Handler
	repeat: { every: number } | { pattern: string }
}

export interface BoundedContextOptions {
	name: string
	root?: boolean
	controllers: Record<string, Constructor<Controller<ZodType, ZodType>>>
	middlewares?: MiddlewareInput
	skipMiddlewares?: MiddlewareInput
	internalHandlers?: HandlerRecord
	externalHandlers?: HandlerRecord
	projectors?: Record<string, new (...args: any[]) => Projector>
	registry?: InstanceRegistry
	jobs?: JobDefinition[]
	setup?: (container: DependencyContainer) => void | Promise<void>
}

export class BoundedContext {
	private constructor(
		readonly container: DependencyContainer,
		readonly router: Router,
	) {}

	static async create(options: BoundedContextOptions): Promise<BoundedContext> {
		const container = options.root ? rootContainer : rootContainer.createChildContainer()

		if (options.registry) {
			registerAll(options.root ? container : rootContainer, options.registry.real)
		}

		autoTrace(container)

		await BoundedContext.registerHandlers(container, options)
		await BoundedContext.registerProjectors(container, options)
		await BoundedContext.registerJobs(container, options.jobs)
		await options.setup?.(container)

		const router = new Router(options.name, container, options.controllers, options.middlewares, options.skipMiddlewares)

		return new BoundedContext(container, router)
	}

	private static async registerHandlers(container: DependencyContainer, options: BoundedContextOptions): Promise<void> {
		if (!options.internalHandlers && !options.externalHandlers) return

		if (options.internalHandlers) {
			const mediator = container.resolve(InternalMediator as any) as InternalMediator
			await Mediator.register(container, mediator, options.internalHandlers)
		}

		if (options.externalHandlers) {
			const mediator = container.resolve(ExternalMediator as any) as ExternalMediator
			await Mediator.register(container, mediator, options.externalHandlers)
		}
	}

	private static async registerProjectors(container: DependencyContainer, options: BoundedContextOptions): Promise<void> {
		if (!options.projectors) return

		const mediator = container.resolve(InternalMediator as any) as InternalMediator
		let successCount = 0

		for (const [projectorName, ProjectorClass] of Object.entries(options.projectors)) {
			if (typeof ProjectorClass !== 'function' || projectorName === 'default') continue

			const result = tryCatch(() => {
				const projectorInstance = container.resolve(ProjectorClass) as Projector

				for (const eventName of projectorInstance.events) {
					// Wrap the projector as a minimal Handler-compatible object for mediator.register
					const pseudoHandler = {
						name: eventName,
						bindContainer: (_c: DependencyContainer) => pseudoHandler,
						execute: async (input: any) => {
							await projectorInstance.handle(input)
						},
					} as any
					mediator.register(pseudoHandler)
				}

				successCount++
			})

			if (!result.success) {
				console.warn(`Failed to resolve Projector ${projectorName}:`, result.error)
			}
		}

		console.log(`✅ Registered ${successCount} Projectors`)
	}

	private static async registerJobs(container: DependencyContainer, jobs?: JobDefinition[]): Promise<void> {
		if (!jobs?.length) return

		const commandQueue = container.resolve(CommandQueue as any) as CommandQueue

		for (const job of jobs) {
			const handler = container.resolve(job.handler).bindContainer(container)
			await commandQueue.registerCommandHandler(handler)
			await commandQueue.enqueueCommand(handler.name, {}, { repeat: job.repeat })
		}
	}
}

import { z, type ZodType } from 'zod'
import { setTimeout as sleep } from 'node:timers/promises'
import { container } from 'tsyringe-neo'

type BodyInit = NonNullable<ConstructorParameters<typeof Response>[0]>
import { Handler } from './Handler'
import {
	HttpControllerRequest,
	HttpControllerResponse,
	HttpMethod,
	HttpMiddlewareResponse,
	MimeTypes,
	HttpControllerError,
	HttpCookie,
	HttpStatusCode,
} from './Http'
import { Middleware, MiddlewareClass } from './Middleware'
import { BaseError } from './BaseError'
import { BaseInterfaceErrors } from '../errors/codes'
import { type AllErrors, GlobalErrorMapper } from '../utils/GlobalErrorMapper'
import { tryCatchAsync } from '../utils/TryCatch'

// Helper to extract examples from Zod schema meta
const getSchemaExamples = (schema: ZodType): unknown[] => {
	const examples = schema?.meta()?.examples as unknown[]
	return examples ?? []
}

export abstract class Controller<InputSchema extends ZodType = ZodType, OutputSchema extends ZodType = ZodType> extends Handler<
	InputSchema,
	OutputSchema
> {
	// Required properties.
	abstract readonly path: `/${string}`
	abstract readonly method: HttpMethod | HttpMethod[]
	abstract readonly description: string

	// Optional properties.
	readonly contentType: MimeTypes = MimeTypes['.json']
	readonly mockController: boolean = false
	middlewares: (Middleware | MiddlewareClass)[] = []
	skipMiddlewares: (Middleware | MiddlewareClass)[] = []

	// Base Properties
	readonly errorMapper = GlobalErrorMapper
	readonly errors: AllErrors[] = []
	readonly baseErrors: AllErrors[] = ['VALIDATION_ERROR']

	// Override input type to wrap in HTTP request
	declare readonly input: HttpControllerRequest<z.output<(typeof this)['inputSchema']>>
	// Override output type to wrap in HTTP response (allows cookies)
	// @ts-expect-error - Intentionally overriding to wrap in HTTP response with cookie support
	declare readonly output: HttpControllerResponse<z.output<(typeof this)['outputSchema']>>

	name = this.constructor.name

	/**
	 * Optional hook for mock controllers to return a custom response (e.g. with cookies).
	 * Receives the validated request. If defined and mockController is true, its return value is used instead of the schema example.
	 */
	protected getMockResponse?(
		_request: z.output<InputSchema>,
	): { status: HttpStatusCode; data: z.output<OutputSchema>; cookie?: Record<string, HttpCookie> } | undefined

	override async execute(input: unknown): Promise<this['output']> {
		const validated = this.validatedRequest(input)
		// handle() returns `this['output'] | void` (Handler base
		// signature widened so void-output handlers can return bare);
		// controllers always return a real response so the cast is
		// type-safe in practice.
		return (await this.handle({ ...(input as Record<string, unknown>), ...validated })) as this['output']
	}

	async executeController(request: HttpControllerRequest<unknown>): Promise<Response> {
		const result = await tryCatchAsync(async () => {
			const middlewareResponse = await this.executeMiddlewares(request)
			if (middlewareResponse) return middlewareResponse
			if (this.mockController) {
				await sleep(600)
				const validated = this.validatedRequest(request)
				const customMock = this.getMockResponse?.(validated as z.output<InputSchema>)
				if (customMock) {
					return this.buildResponse({
						status: customMock.status,
						data: customMock.data,
						cookie: customMock.cookie,
					})
				}
				const examples = getSchemaExamples(this.outputSchema)
				const firstOutputExample = examples[0]
				if (!firstOutputExample) throw new BaseError<BaseInterfaceErrors>('INVALID_CONTROLLER_EXAMPLES')
				return this.buildResponse({
					status: HttpStatusCode.OK,
					data: firstOutputExample,
				})
			}
			const response = await this.execute(request)
			if (response instanceof Response) return response
			return this.buildResponse(response)
		})
		if (!result.success) {
			return this.handleError(result.error)
		}
		return result.data
	}

	private async executeMiddlewares(request: HttpControllerRequest<unknown>): Promise<Response | undefined> {
		const blacklist = new Set(
			this.skipMiddlewares.map(skip => {
				if (typeof skip === 'function') return skip.name
				return skip.constructor.name
			}),
		)

		for (const middlewareOrClass of this.middlewares) {
			let middleware: Middleware
			if (typeof middlewareOrClass === 'function') {
				middleware = container.resolve(middlewareOrClass)
			} else {
				middleware = middlewareOrClass
			}

			if (blacklist.has(middleware.constructor.name)) {
				continue
			}

			const middlewareResponse = await middleware.execute(request)
			this.applyMiddlewareResponse(request, middlewareResponse)

			// If middleware returns a status, build and return the response early
			if (middlewareResponse.status) {
				return this.buildMiddlewareResponse(middlewareResponse)
			}
		}
	}

	private buildMiddlewareResponse(middlewareResponse: HttpMiddlewareResponse<unknown>): Response {
		const { status, headers, cookie } = middlewareResponse
		const response = new Response(null, { status })
		this.setResponseHeaders(response, headers)
		this.setResponseCookies(response, cookie)
		return response
	}

	private applyMiddlewareResponse(request: HttpControllerRequest<unknown>, middlewareResponse: HttpMiddlewareResponse<unknown>): void {
		const { cookie, headers } = middlewareResponse
		if (cookie) request.cookie = { ...request.cookie, ...cookie }
		if (headers) request.headers = { ...request.headers, ...this.filterUndefinedValues(headers) }
	}

	private filterUndefinedValues<T extends Record<string, unknown>>(obj: T): Partial<T> {
		return Object.fromEntries(Object.entries(obj).filter(([, value]) => value !== undefined)) as Partial<T>
	}

	private buildResponse(controllerResponse: HttpControllerResponse<z.output<ZodType>>): Response {
		const { status, data, headers, cookie } = controllerResponse
		const isVoid = data === undefined || data === null
		const body = isVoid ? null : this.serializeBody(data)
		const responseStatus = isVoid && status === HttpStatusCode.OK ? HttpStatusCode.NO_CONTENT : status
		const response = new Response(body, { status: responseStatus })
		if (!isVoid) this.setContentType(response)
		this.setResponseHeaders(response, headers)
		this.setResponseCookies(response, cookie)
		return response
	}

	private serializeBody(data: unknown): BodyInit {
		if (this.isBodyInit(data)) {
			return data as BodyInit
		}
		return JSON.stringify(data)
	}

	private isBodyInit(data: unknown): data is BodyInit {
		return (
			data !== undefined &&
			data !== null &&
			(data instanceof Blob ||
				data instanceof FormData ||
				data instanceof URLSearchParams ||
				data instanceof ReadableStream ||
				data instanceof ArrayBuffer ||
				typeof data === 'string' ||
				ArrayBuffer.isView(data))
		)
	}

	private setResponseHeaders(response: Response, headers?: Record<string, string | undefined>): void {
		if (!headers) return
		Object.entries(headers).forEach(([key, value]) => {
			if (value !== undefined) {
				response.headers.set(key, value)
			}
		})
	}

	private setResponseCookies(response: Response, cookies?: Record<string, HttpCookie>): void {
		if (!cookies) return
		Object.entries(cookies).forEach(([key, cookie]) => {
			if (cookie.value) {
				const cookieString = this.buildCookieString(key, cookie)
				response.headers.append('Set-Cookie', cookieString)
			}
		})
	}

	private buildCookieString(key: string, cookie: HttpCookie): string {
		const cookieString = `${key}=${cookie.value}`
		const attributes = this.buildCookieAttributes(cookie)
		return attributes ? `${cookieString}; ${attributes}` : cookieString
	}

	private buildCookieAttributes(cookie: HttpCookie): string {
		return Object.entries(cookie)
			.filter(([attr, value]) => attr !== 'value' && value !== undefined)
			.map(([attr, value]) => `${attr}=${value}`)
			.join('; ')
	}

	private setContentType(response: Response): void {
		if (this.contentType) {
			response.headers.set('Content-Type', this.contentType)
		}
	}

	private handleError(error: unknown): Response {
		if (error instanceof BaseError) {
			const { name, message } = error
			const status = this.errorMapper[name as AllErrors] ?? HttpStatusCode.INTERNAL_SERVER_ERROR
			throw new HttpControllerError(name, status, message)
		}
		throw error
	}
}

