 *
 * When the SDK is not started, the OpenTelemetry API returns noop tracers/spans
 * automatically — every startSpan, setAttribute, addEvent call becomes a zero-cost
 * noop. This means autoTrace can wrap every class unconditionally: in dev without
 * a collector there is zero memory overhead, and in production with a collector
 * all classes are traced with proper bounds.
 */
export async function startTelemetry() {
	if (!process.env.OTEL_COLLECTOR_TRACE_URL) {
		console.log('⏭️  OTEL_COLLECTOR_TRACE_URL not set — telemetry disabled (noop spans)')
		return
	}

	const sdk = new NodeSDK({
		serviceName: Config.name,
		contextManager,
		instrumentations: [],
		spanProcessors: [
			new BatchSpanProcessor(
				new OTLPTraceExporter({
					url: Config.env.OTEL_COLLECTOR_TRACE_URL,
				}),
				{
					maxQueueSize: 2048,
					maxExportBatchSize: 512,
					scheduledDelayMillis: 5000,
				},
			),
		],
	})
	await sdk.start()
	console.log(`✅ Telemetry started → ${Config.env.OTEL_COLLECTOR_TRACE_URL}`)
}

/**
 * Describe a value for tracing without serializing it.
 * Returns a short, fixed-size string like "Object{3 keys}", "Array[5]", "string(42)", etc.
 * No JSON.stringify — zero large allocations.
 */
export function describeValue(value: unknown): string {
	if (value === null) return 'null'
	if (value === undefined) return 'undefined'
	if (typeof value === 'string') return `string(${value.length})`
	if (typeof value === 'number' || typeof value === 'boolean') return String(value)
	if (Array.isArray(value)) return `Array[${value.length}]`
	if (value instanceof Error) return `${value.constructor.name}: ${value.message.slice(0, 100)}`
	if (typeof value === 'object') {
		const name = value.constructor?.name
		const keys = Object.keys(value as object)
		return name && name !== 'Object' ? `${name}{${keys.length} keys}` : `Object{${keys.length} keys}`
	}
	return typeof value
}

function addIOAttributes(span: Span, args: unknown[], result?: unknown) {
	if (args.length === 1) {
		span.setAttribute('method.input', describeValue(args[0]))
	} else if (args.length > 1) {
		span.setAttribute('method.input', `[${args.map(describeValue).join(', ')}]`)
	}
	if (result !== undefined) {
		span.setAttribute('method.output', describeValue(result))
	}
}

function addErrorIOEvents(span: Span, args: unknown[]) {
	span.addEvent('method.input', { 'input.description': `[${args.map(describeValue).join(', ')}]` })
}

// Utility function to add tracing to class methods
function traceClassMethods(prototype: any, className: string, module?: string) {
	Object.getOwnPropertyNames(prototype).forEach(methodName => {
		if (methodName === 'constructor') return

		const descriptor = Object.getOwnPropertyDescriptor(prototype, methodName)

		if (descriptor && typeof descriptor.value === 'function' && descriptor.writable) {
			const originalMethod = descriptor.value
			const isAsync = originalMethod.constructor.name === 'AsyncFunction'

			Object.defineProperty(prototype, methodName, {
				value: isAsync
					? async function (this: any, ...args: any[]) {
							const ctx = context.active()
							const tracer = trace.getTracer(Config.name)
							const span = tracer.startSpan(`${className}.${methodName}`, {}, ctx)
							return await context.with(trace.setSpan(ctx, span), async () => {
								try {
									span.setAttribute('class.name', className)
									span.setAttribute('class.component', getComponentFromClassName(className))
									span.setAttribute('class.module', module || 'unknown')
									span.setAttribute('method.name', methodName)
									span.setAttribute('method.type', 'async')
									span.setAttribute('method.args.count', args.length)

									const startTime = Date.now()
									const result = await originalMethod.apply(this, args)

									span.setAttribute('method.duration.ms', Date.now() - startTime)
									addIOAttributes(span, args, result)

									return result
								} catch (error) {
									addErrorIOEvents(span, args)
									span.recordException(error as Error)
									span.setAttribute('method.error.type', (error as Error)?.constructor?.name || 'unknown')
									span.setAttribute('method.error.message', (error as Error)?.message || 'unknown error')
									span.setStatus({
										code: SpanStatusCode.ERROR,
										message: (error as Error)?.message || 'Internal Server Error',
									})
									throw error
								} finally {
									span.end()
								}
							})
						}
					: function (this: any, ...args: any[]) {
							const ctx = context.active()
							const tracer = trace.getTracer(Config.name)
							const span = tracer.startSpan(`${className}.${methodName}`, {}, ctx)
							return context.with(trace.setSpan(ctx, span), () => {
								try {
									span.setAttribute('class.name', className)
									span.setAttribute('class.component', getComponentFromClassName(className))
									span.setAttribute('class.module', module || 'unknown')
									span.setAttribute('method.name', methodName)
									span.setAttribute('method.type', 'sync')
									span.setAttribute('method.args.count', args.length)

									const startTime = Date.now()
									const result = originalMethod.apply(this, args)

									span.setAttribute('method.duration.ms', Date.now() - startTime)
									addIOAttributes(span, args, result)

									return result
								} catch (error) {
									addErrorIOEvents(span, args)
									span.recordException(error as Error)
									span.setAttribute('method.error.type', (error as Error)?.constructor?.name || 'unknown')
									span.setAttribute('method.error.message', (error as Error)?.message || 'unknown error')
									throw error
								} finally {
									span.end()
								}
							})
						},
				writable: true,
				configurable: true,
			})
		}
	})
}

export function traceClass(classes: any[]) {
	classes.forEach(clazz => {
		traceClassMethods(clazz.prototype, clazz.name)
	})
}

// Intercept container.resolve to apply tracing to all resolved classes
export function autoTrace(container: DependencyContainer, context?: string) {
	const originalResolve = container.resolve

	container.resolve = function <T>(this: typeof container, token: any): T {
		const service = originalResolve.call(this, token)

		if (service && typeof service === 'object') {
			const classConstructor = service.constructor
			const className = classConstructor.name

			if (!tracedClasses.has(className)) {
				traceClassMethods(classConstructor.prototype, className, context)
				tracedClasses.add(className)
			}
		}

		return service as T
	} as typeof container.resolve
}

function getComponentFromClassName(className: string): string {
	const components = ['router', 'middleware', 'controller', 'service', 'repository', 'handler', 'factory', 'event', 'mediator']
	return components.filter(component => className.toLowerCase().includes(component.toLowerCase())).at(-1) || 'unknown'
}

/* eslint-disable @typescript-eslint/no-unsafe-function-type */

// Para ValueObjects compostos (Phone, Holder, etc.)
export abstract class ValueObject {
	toJSON(): RecursiveValueObjectProps<this> {
		const objectsMap = Object.entries({ ...this })
		const objected = Object.fromEntries(
			objectsMap.map(([key, value]) => {
				// Check PrimitiveValueObject first (more specific)
				if (value instanceof PrimitiveValueObject) {
					return [key, value.toJSON()]
				}
				if (value instanceof ValueObject) {
					return [key, value.toJSON()]
				}
				if (Array.isArray(value)) {
					return [
						key,
						value.map(item => {
							if (item instanceof PrimitiveValueObject) return item.toJSON()
							if (item instanceof ValueObject) return item.toJSON()
							return item
						}),
					]
				}
				// ... rest
				return [key, value]
			}),
		)
		return objected as RecursiveValueObjectProps<this>
	}
}
// Para ValueObjects primitivos (Email, Id, etc.)
export abstract class PrimitiveValueObject<T> {
	abstract readonly value: T

	toJSON(): T {
		return this.value
	}

	toString(): string {
		return String(this.value)
	}
}

// Utility type to strip functions from a type
type StripFunctions<T> = {
	[K in keyof T as T[K] extends Function ? never : K]: T[K]
}

// Utility type to extract properties from a ValueObject instance (excluding methods)
type ValueObjectProps<T extends ValueObject> = StripFunctions<Omit<T, keyof ValueObject>>

// Built-in types that should be preserved as-is
type BuiltInObjects =
	| Date
	| RegExp
	| Error
	| Map<unknown, unknown>
	| Set<unknown>
	| WeakMap<object, unknown>
	| WeakSet<object>
	| Function
	| Promise<unknown>
	| ArrayBuffer
	| DataView
	| Int8Array
	| Uint8Array
	| Uint8ClampedArray
	| Int16Array
	| Uint16Array
	| Int32Array
	| Uint32Array
	| Float32Array
	| Float64Array
	| BigInt64Array
	| BigUint64Array

type TransformProperty<T> = T extends BuiltInObjects
	? T
	: T extends PrimitiveValueObject<infer V>
		? V
		: T extends ValueObject
			? RecursiveValueObjectProps<T>
			: T extends readonly (infer U)[]
				? TransformProperty<U>[]
				: T extends object
					? { [K in keyof T]: TransformProperty<T[K]> }
					: T

type RecursiveValueObjectProps<T> = T extends ValueObject
	? {
			[K in keyof ValueObjectProps<T>]: TransformProperty<ValueObjectProps<T>[K]>
		}
	: TransformProperty<T>

export type { ValueObjectProps, RecursiveValueObjectProps }

import { BasePrimitiveValueObject } from './BasePrimitiveValueObject'
import type { BaseDomainErrors } from '../errors/codes'
import { createHash } from 'node:crypto'
import { uuidv7 } from 'uuidv7'
import z from 'zod'

export const IdSchema = z.string().refine(v => v.length > 0, { error: 'INVALID_ID' as BaseDomainErrors })

// Locked UUIDv5 namespace — byte-for-byte identical to `packages/api/go/core/objects/id.go`.
// Changing this orphans every previously-ingested deterministic id. Not exported.
const BK_DASH_NAMESPACE = 'f63cfbe6-7d8e-4d1d-9c5d-9d8a8b1b0c5e' as const

export class Id extends BasePrimitiveValueObject<typeof IdSchema> {
	static override schema = IdSchema

	constructor(value?: string) {
		super(value ?? Id.value())
	}

	/**
	 * Fresh primitive id string (UUIDv7). Use when an external library
	 * needs a raw id generator and we don't want to leak uuidv7 imports
	 * across the codebase.
	 */
	static value(): string {
		return uuidv7()
	}

	/**
	 * Deterministic UUIDv5 from a tuple of strings, using the locked
	 * `BK_DASH_NAMESPACE`. Same algorithm + namespace as Go's
	 * `objects.IDFromSeed(...)` — identical inputs produce identical UUIDs
	 * across languages.
	 *
	 * Implementation: RFC 4122 UUIDv5 = SHA-1(namespace_bytes || name_bytes)
	 * with version + variant bits set per spec. Inlined to avoid a `uuid`
	 * package dependency.
	 */
	static fromSeed(...parts: string[]): Id {
		if (parts.length === 0) throw new Error('Id.fromSeed requires at least one part')
		const name = parts.join(':')

		const namespaceBytes = Buffer.from(BK_DASH_NAMESPACE.replace(/-/g, ''), 'hex')
		const hash = createHash('sha1').update(namespaceBytes).update(name, 'utf8').digest()

		// Set UUIDv5 version (0x50 in byte 6) and RFC 4122 variant (0x80 in byte 8).
		hash[6] = (hash[6]! & 0x0f) | 0x50
		hash[8] = (hash[8]! & 0x3f) | 0x80

		const hex = hash.subarray(0, 16).toString('hex')
		const uuid = `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-` + `${hex.slice(16, 20)}-${hex.slice(20, 32)}`
		return new Id(uuid)
	}

	equals(other: Id): boolean {
		return this.value === other.value
	}

	override toString(): string {
		return this.value
	}
}

import { trace, context, Span } from '@opentelemetry/api'
import Fastify, { FastifyInstance, FastifyReply, FastifyRequest } from 'fastify'
import { Readable } from 'node:stream'
import { Controller } from '../../types/Controller'
import { type HttpMethod, type HttpControllerRequest, type HttpCookie, HttpStatusCode, HttpControllerError } from '../../types/Http'
import { Config } from '../../utils/Config'
import { HttpRouter } from '.'
import { injectable } from 'tsyringe-neo'

@injectable()
export class FastifyHttpRouter implements HttpRouter {
	private app: FastifyInstance
	private listening = false

	constructor() {
		this.app = Fastify({ logger: false, bodyLimit: 10 * 1024 * 1024 })

		// Buffer all bodies as Buffer so we can both parse them ourselves
		// and feed the raw bytes to a constructed Web Request (used by
		// Better Auth's `auth.handler(request)` and the channel proxy).
		this.app.removeAllContentTypeParsers()
		this.app.addContentTypeParser('*', { parseAs: 'buffer' }, (_req, body, done) => done(null, body))

		this.app.options('/*', async (req, reply) => this.handleCorsPreflight(req, reply))
	}

	async on(path: string, method: HttpMethod | HttpMethod[], controller: Controller): Promise<void> {
		const methods = Array.isArray(method) ? method : [method]

		for (const m of methods) {
			this.app.route({
				method: m.toUpperCase() as 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH',
				url: path,
				handler: async (req, reply) => {
					const tracer = trace.getTracer(Config.name)
					const span = tracer.startSpan(`${req.method} ${path}`, { root: true })

					this.addHttpAttributes(span, req)

					return context.with(trace.setSpan(context.active(), span), async () => {
						try {
							await this.handleControllerRequest(req, reply, controller, span)
						} catch (error) {
							await this.handleError(error, req, reply, span)
						} finally {
							span.end()
						}
					})
				},
			})
		}
	}

	async listen(port: number): Promise<void> {
		await this.app.listen({ port, host: '0.0.0.0' })
		this.listening = true
	}

	async stop(): Promise<void> {
		if (this.listening) {
			await this.app.close()
			this.listening = false
			console.log('✅ HTTP server stopped')
		}
	}

	isRunning(): boolean {
		return this.listening
	}

	private async handleControllerRequest(req: FastifyRequest, reply: FastifyReply, controller: Controller, span: Span): Promise<void> {
		const controllerRequest = await this.buildControllerRequest(req)
		const response = await controller.executeController(controllerRequest)

		span.setAttribute('http.status_code', response.status)
		span.setAttribute('http.timestamp.end', Date.now())

		const corsHeaders = this.getCorsHeaders(req)
		await this.sendWebResponse(reply, response, corsHeaders)
	}

	private async buildControllerRequest(req: FastifyRequest): Promise<HttpControllerRequest<unknown>> {
		const bodyBuffer = (req.body as Buffer | undefined) ?? Buffer.alloc(0)
		const jsonBody =
			bodyBuffer.length > 0 && (req.headers['content-type'] ?? '').includes('json')
				? (JSON.parse(bodyBuffer.toString('utf8')) as Record<string, unknown>)
				: undefined

		// Preserve repeated query params as arrays (e.g. ?id=a&id=b -> ['a','b']).
		// Array-typed filters rely on this; the `z.stringToArray(element)` helper
		// normalizes single string | string[] | comma-separated into a typed array.
		const query: Record<string, string | string[] | undefined> = {}
		const fastifyQuery = req.query as Record<string, string | string[]>
		for (const [key, value] of Object.entries(fastifyQuery)) {
			query[key] = value
		}

		const params = (req.params as Record<string, string>) ?? {}

		const cookieHeader = req.headers.cookie
		const parsedCookies: Record<string, HttpCookie> = {}
		if (cookieHeader) {
			cookieHeader.split(';').forEach(cookie => {
				const [key, value] = cookie.trim().split('=')
				if (key && value) {
					parsedCookies[key] = { value, HttpOnly: true, Secure: true, SameSite: 'lax' }
				}
			})
		}

		const headers: Record<string, string> = {}
		for (const [k, v] of Object.entries(req.headers)) {
			if (Array.isArray(v)) headers[k] = v.join(', ')
			else if (v != null) headers[k] = String(v)
		}

		return {
			url: this.fullUrl(req),
			body: jsonBody as Record<string, unknown>,
			headers,
			params,
			query,
			cookie: parsedCookies,
			ctx: {},
			raw: this.buildWebRequest(req, bodyBuffer),
		}
	}

	private buildWebRequest(req: FastifyRequest, body: Buffer): Request {
		const url = this.fullUrl(req)

		const webHeaders = new Headers()
		for (const [k, v] of Object.entries(req.headers)) {
			// biome-ignore lint/suspicious/useIterableCallbackReturn: <explanation>
			if (Array.isArray(v)) v.forEach(vv => webHeaders.append(k, vv))
			else if (v != null) webHeaders.set(k, String(v))
		}

		// Hook the Node socket close to a Web AbortSignal so that consumers
		// using `request.raw.signal` (SSE streams, Better Auth) detect client
		// disconnects.
		const ac = new AbortController()
		req.raw.once('close', () => ac.abort())

		const method = req.method.toUpperCase()
		const hasBody = !['GET', 'HEAD'].includes(method) && body.length > 0

		return new Request(url, {
			method,
			headers: webHeaders,
			// Node Buffer is a valid request body at runtime. The cast is
			// lib-agnostic: `BodyInit` only exists once DOM types are pulled in
			// transitively (via the SDK http module on the api-typescript build);
			// core compiles without DOM, so we can't name BodyInit here.
			body: hasBody ? (body as unknown as undefined) : undefined,
			signal: ac.signal,
		})
	}

	private fullUrl(req: FastifyRequest): string {
		const proto = (req.headers['x-forwarded-proto'] as string | undefined) ?? (req.protocol || 'http')
		const host = req.headers.host ?? 'localhost'
		return `${proto}://${host}${req.url}`
	}

	private addHttpAttributes(span: Span, req: FastifyRequest): void {
		const url = new URL(this.fullUrl(req))

		span.setAttribute('http.method', req.method.toUpperCase())
		span.setAttribute('http.route', url.pathname)
		span.setAttribute('http.url', url.toString())
		span.setAttribute('http.scheme', url.protocol.replace(':', ''))
		span.setAttribute('http.user_agent', String(req.headers['user-agent'] ?? 'unknown'))
		span.setAttribute('http.host', String(req.headers.host ?? 'unknown'))
		span.setAttribute('http.content_length', String(req.headers['content-length'] ?? '0'))

		if (url.search) {
			span.setAttribute('http.query_string', url.search.substring(1))
		}

		const forwardedFor = req.headers['x-forwarded-for']
		if (forwardedFor) {
			span.setAttribute('http.x_forwarded_for', String(forwardedFor))
		}

		for (const [key, value] of Object.entries((req.params as Record<string, string>) ?? {})) {
			if (value) span.setAttribute(`http.params.${key}`, String(value))
		}
	}

	private async sendWebResponse(reply: FastifyReply, response: Response, corsHeaders: Record<string, string> | null): Promise<void> {
		reply.status(response.status)

		response.headers.forEach((value, key) => {
			reply.header(key, value)
		})

		if (corsHeaders) {
			for (const [key, value] of Object.entries(corsHeaders)) {
				reply.header(key, value)
			}
		}

		if (!response.body) {
			await reply.send()
			return
		}

		const nodeStream = Readable.fromWeb(response.body as unknown as Parameters<typeof Readable.fromWeb>[0])
		await reply.send(nodeStream)
	}

	private async handleError(error: unknown, req: FastifyRequest, reply: FastifyReply, span: Span): Promise<void> {
		const corsHeaders = this.getCorsHeaders(req)

		if (error instanceof HttpControllerError) {
			const { status, message, name } = error
			const statusCode = status ?? HttpStatusCode.INTERNAL_SERVER_ERROR

			span.setAttribute('http.status_code', Number(statusCode))
			span.setAttribute('http.error', true)
			span.setAttribute('http.error.name', name)
			span.setAttribute('http.error.message', message)
			span.setAttribute('http.error.type', error.constructor.name)
			span.recordException(error)

			reply.status(Number(statusCode)).header('Content-Type', 'application/json')
			if (corsHeaders) {
				for (const [k, v] of Object.entries(corsHeaders)) reply.header(k, v)
			}
			await reply.send({ code: name, ...(message ? { message } : undefined) })
			return
		}

		span.setAttribute('http.status_code', HttpStatusCode.INTERNAL_SERVER_ERROR)
		span.setAttribute('http.error', true)
		span.setAttribute('http.error.message', 'Unknown error')
		span.setAttribute('http.error.type', 'UnknownError')
		span.recordException(error instanceof Error ? error : new Error(String(error)))

		reply.status(HttpStatusCode.INTERNAL_SERVER_ERROR).header('Content-Type', 'application/json')
		if (corsHeaders) {
			for (const [k, v] of Object.entries(corsHeaders)) reply.header(k, v)
		}
		await reply.send({ code: 'INTERNAL_SERVER_ERROR' })
	}

	private async handleCorsPreflight(req: FastifyRequest, reply: FastifyReply): Promise<void> {
		const corsHeaders = this.getCorsHeaders(req)

		if (!corsHeaders) {
			await reply.status(403).send('CORS policy violation')
			return
		}

		reply.status(204)
		for (const [key, value] of Object.entries(corsHeaders)) {
			reply.header(key, value)
		}
		reply.header('Access-Control-Max-Age', '86400')
		await reply.send()
	}

	private getCorsHeaders(req: FastifyRequest): Record<string, string> | null {
		const origin = req.headers.origin as string | undefined
		const allowedOrigins = Config.env.CORS_ALLOWED_ORIGINS

		const isAllowed = allowedOrigins.includes('*') || (!!origin && allowedOrigins.includes(origin))
		if (!isAllowed) return null

		const allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With', 'x-account-id']

		return {
			'Access-Control-Allow-Origin': origin || '*',
			'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, PATCH, OPTIONS',
			'Access-Control-Allow-Headers': allowedHeaders.join(', '),
			'Access-Control-Allow-Credentials': 'true',
		}
	}
}

import { BaseInfrastructureErrors } from '../../errors/codes'
import { BaseEvent } from '../../types/BaseEvent'
import { BaseError } from '../../types/BaseError'
import { Handler } from '../../types/Handler'
import { tryCatchAsync } from '../../utils/TryCatch'
import EventEmitter2 from 'eventemitter2'
import { EventCallback, Mediator, Unsubscribe, handlerEventNames } from '.'
import { injectable } from 'tsyringe-neo'

@injectable()
export class EventEmitter2Mediator extends Mediator {
	private readonly eventEmitter = new EventEmitter2({
		wildcard: true,
	})

	private registeredHandlers = new Set<string>()
	private handlerMap = new Map<string, Handler[]>()

	async register(handler: Handler): Promise<void> {
		const names = handlerEventNames(handler)
		for (const name of names) {
			// If already registered for this event name, remove the old EventEmitter2
			// listener and handler map entry before re-adding so we never accumulate
			// stale listeners.
			if (this.registeredHandlers.has(name)) {
				console.warn(`Handler ${name} already registered, replacing existing registration`)
				this.eventEmitter.removeAllListeners(name)
				this.handlerMap.delete(name)
				this.registeredHandlers.delete(name)
			}

			this.registeredHandlers.add(name)

			// Store handler reference for dispatch() (synchronous, error-propagating)
			if (!this.handlerMap.has(name)) {
				this.handlerMap.set(name, [])
			}
			this.handlerMap.get(name)!.push(handler)

			// Register for publish() (fire-and-forget via EventEmitter2)
			this.eventEmitter.on(name, async (event: BaseEvent) => {
				void tryCatchAsync(async () => handler.execute(event))
			})
		}
	}

	async publish(event: BaseEvent): Promise<void> {
		this.eventEmitter.emit(event.name, event)
	}

	async dispatch(event: BaseEvent): Promise<void> {
		const handlers = this.handlerMap.get(event.name)

		if (!handlers || handlers.length === 0) {
			return
		}

		for (const handler of handlers) {
			await handler.execute(event)
		}
	}

	async execute<T extends Handler>(_handler: T['name'], _input: T['input']): Promise<T['output']> {
		throw new BaseError<BaseInfrastructureErrors>('NOT_IMPLEMENTED')
	}

	removeAllListeners(): void {
		this.eventEmitter.removeAllListeners()
		this.registeredHandlers.clear()
		this.handlerMap.clear()
		console.log('✅ Removed all event listeners')
	}

	getHandlerCount(): number {
		return this.registeredHandlers.size
	}

	registerCallback(callback: EventCallback, eventName?: string): Unsubscribe {
		const event = eventName ?? '**'
		this.eventEmitter.on(event, callback)
		return () => {
			this.eventEmitter.off(event, callback)
		}
	}
}
